icone <- function(nome) {
  p <- switch(nome,
    inicio='<path d="M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
    mapa='<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15M15 6v15"/>',
    espacial='<circle cx="5" cy="5" r="2"/><circle cx="19" cy="6" r="2"/><circle cx="9" cy="18" r="2"/><circle cx="19" cy="19" r="2"/><path d="m7 5 10 1M6 7l2 9m3 2 6 1m2-11v9M7 7l10 10"/>',
    tempo='<path d="M4 4v16h17M7 15l4-5 4 2 5-7"/>',
    perfil='<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2M9 21v-4m6 4v-4"/>',
    dados='<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 4 16 4 16 0V5M4 12v7c0 4 16 4 16 0v-7"/>',
    seta='<path d="M5 12h14m-6-6 6 6-6 6"/>',
    '<circle cx="12" cy="12" r="9"/>')
  HTML(paste0('<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">',p,'</svg>'))
}
card <- function(titulo,subtitulo=NULL,...,classe="") div(class=paste("cartao",classe),
  div(class="cartao-cabecalho",div(h3(titulo),if(!is.null(subtitulo)) p(subtitulo))),...)
secao <- function(id,...) conditionalPanel(paste0("input.pagina == '",id,"'"),div(class="pagina",...))
ui_painel <- function() fluidPage(
  theme=bslib::bs_theme(version=5,primary="#327C72",base_font="system-ui",bg="#F4F6F7",fg="#213D40"),
  tags$head(tags$title("Intoxicações no Paraná · Painel de pesquisa"),
    tags$meta(name="viewport",content="width=device-width, initial-scale=1"),
    tags$link(rel="stylesheet",href="app.css"),tags$link(rel="stylesheet",href="acessibilidade.css"),tags$link(rel="stylesheet",href="exploracao.css"),tags$script(src="app.js")),
  div(class="aplicacao",
    tags$aside(class="lateral",id="lateral",
      div(class="marca",div(class="marca-simbolo","i",tags$span("PR")),div(tags$b("Intoxicações"),tags$span("PARANÁ · 15–29 ANOS"))),
      div(class="lateral-rotulo","EXPLORAR O ESTUDO"),
      tags$nav(`aria-label`="Navegação principal",
        lapply(list(c("visao","inicio","Visão geral"),c("territorio","mapa","Território"),c("espacial","espacial","Análise espacial"),c("tempo","tempo","Evolução temporal"),c("municipal","perfil","Ficha municipal"),c("metodo","dados","Método e dados")),function(a)
          tags$button(type="button",class=paste("nav-item",if(a[1]=="visao") "ativo" else ""),`data-pagina`=a[1],icone(a[2]),tags$span(a[3])))),
      div(class="lateral-nota",span(class="ponto-status"),"Painel de pesquisa",p("Notificações de intoxicação autoprovocada em jovens residentes no Paraná.")),
      div(class="lateral-rodape",span("FONTE"),strong("SINAN / DATASUS"),p("Dados agregados por município e ano."))),
    tags$main(class="principal",id="conteudo",
      div(class="topo",div(class="trilha",tags$button(id="menu-mobile",type="button",`aria-label`="Abrir navegação","☰"),span("PESQUISA EPIDEMIOLÓGICA"),span(class="trilha-divisor","/"),span("PARANÁ")),
        div(class="topo-direita",span(class="badge-jovens","15–29 anos"),uiOutput("selo_base"))),
      div(class="miolo",
        div(class="cabecalho-pagina",uiOutput("titulo_pagina"),div(class="seletor-base",selectInput("versao","VERSÃO DOS DADOS",choices=c("Estudo confirmado · 2014–2025"="estudo"),width="100%"))),
        uiOutput("aviso_versao"),
        uiOutput("fonte_dados"),
        conditionalPanel("input.pagina != 'metodo'",div(class="filtros",
          div(class="filtro-municipio",selectizeInput("municipio","MUNICÍPIO",choices=c("Todo o Paraná"="todos"),options=list(placeholder="Busque um município..."))),
          conditionalPanel("input.pagina == 'visao' || input.pagina == 'tempo' || input.pagina == 'municipal'",div(class="filtro-periodo",sliderInput("anos","PERÍODO DE NOTIFICAÇÃO",min=2014,max=2025,value=c(2021,2025),step=1,sep=""))),
          actionButton("limpar","Redefinir",class="botao-secundario"))),
        conditionalPanel("input.pagina == 'territorio' || input.pagina == 'espacial' || input.pagina == 'tempo'",uiOutput("municipio_em_foco")),
        secao("visao",
          uiOutput("kpis"),
          div(class="grade grade-principal",
            card("Notificações ao longo do tempo","Cada registro representa uma notificação, não uma pessoa única.",uiOutput("grafico_notificacoes"),div(class="cartao-rodape",uiOutput("contexto_serie"),downloadLink("baixar_serie","↓ Baixar série"))),
            card("Distribuição no território","Clique em um município para explorar seus resultados.",div(class="mapa-controle",selectInput("medida_mapa",NULL,c("Notificações"="CASOS","Taxa por 100 mil"="TAXA"),width="190px")),leaflet::leafletOutput("mapa_visao",height=300),div(class="cartao-rodape",span("Município de residência"),span("399 municípios")))),
          div(class="grade grade-tres",
            card("Perfil por sexo","Proporção das notificações no recorte selecionado.",uiOutput("perfil_sexo")),
            card("Faixa etária","Contagens entre 15 e 29 anos.",uiOutput("perfil_idade")),
            card("Agentes tóxicos","Seis categorias mais frequentes no recorte.",uiOutput("perfil_agentes"))),
          div(class="nota-rodape","SINAN / DATASUS · Notificações sujeitas a revisão. Contagens de 2026, quando disponíveis, são parciais.")),
        secao("territorio",
          div(class="faixa-contexto",icone("mapa"),div(strong("Recorte espacial · 2021–2025"),span("Comparação municipal das taxas anuais médias, na mesma escala de 100 mil jovens."))),
          div(class="grade grade-mapa",
            card("Taxas municipais","A suavização Bayes considera a população e a vizinhança espacial.",selectInput("indicador_territorio","INDICADOR",c("Bayes empírico espacial"="TAXA_BAYES_100MIL","Taxa bruta anual média"="TAX1529_MED","Notificações no quinquênio"="CAS1529_TOT")),leaflet::leafletOutput("mapa_territorio",height=440)),
            card("Explorar municípios","Ordene as colunas ou busque um município na tabela.",DT::DTOutput("tabela_territorio"),div(class="cartao-rodape",span("Recorte completo de 399 municípios"),downloadLink("baixar_territorio","↓ Baixar dados")))),
          div(class="nota-metodo",strong("Como ler as taxas"),p("Taxa bruta anual média = soma das notificações ÷ soma das populações anuais × 100.000. A taxa Bayes é a estimativa espacial local TXMDCMDPO × 100.000. Os valores suavizados não representam contagens observadas."))),
        secao("espacial",
          uiOutput("aviso_lisa"),
          div(class="grade grade-moran",
            div(class="cartao moran-destaque",span(class="eyebrow","AUTOCORRELAÇÃO GLOBAL · 2021–2025"),uiOutput("moran_valor"),p("Municípios com valores semelhantes tendem a estar próximos."),div(class="moran-detalhes",uiOutput("moran_p"),span("Queen · pesos W · 999 permutações"))),
            card("Diagrama de Moran","Taxa Bayes e sua defasagem espacial; cada ponto é um município.",uiOutput("dispersao_moran"))),
          div(class="grade grade-mapa",
            card("Associação espacial local · LISA","Resultados para 2021–2025; significância em p < 0,05.",selectInput("metodo_lisa","VERSÃO DO LISA",choices=c("Permutação em R · oficial do estudo"="PRM","Analítico em R · comparação"="ANA","Referência histórica · mapa prévio"="OFIC")),leaflet::leafletOutput("mapa_lisa",height=430)),
            card("Padrões locais","Associação em relação à distribuição municipal do Paraná.",uiOutput("resumo_lisa"),uiOutput("detalhe_lisa"),downloadLink("baixar_lisa","↓ Baixar LISA desta versão",class="botao-link")))),
        secao("tempo",
          ui_cubo(),
          div(class="grade grade-principal",
            card("Evolução das taxas","Taxas por 100 mil jovens; o recorte acompanha o filtro de período.",uiOutput("grafico_taxas"),uiOutput("legenda_taxas")),
            card("Moran global a cada ano","Autocorrelação das taxas Bayes no Paraná, calculada para os 399 municípios.",uiOutput("grafico_moran_anual"),div(class="cartao-rodape",span("A seleção municipal não altera este índice estadual.")))),
          div(class="faixa-contexto",icone("tempo"),div(strong("Tendências municipais · série completa de 2014–2025"),span("Mann–Kendall e inclinação de Sen sobre as taxas Bayes anuais; este resultado não muda com o filtro de período."))),
          div(class="grade grade-mapa",
            card("Mapa de tendências","Aumento ou queda significativa em p < 0,05.",leaflet::leafletOutput("mapa_tendencia",height=410)),
            card("Série espaço-temporal","Painel municipal em formato longo: município × ano.",uiOutput("kpis_tendencia"),DT::DTOutput("tabela_tendencias"),div(class="cartao-rodape",downloadLink("baixar_cubo","↓ Painel município × ano"),downloadLink("baixar_tendencias","↓ Tendências"))))),
        secao("municipal",ui_ficha()),
        secao("metodo",
          div(class="grade grade-principal",
            card("Atualização automática","Coleta periódica diretamente do repositório oficial do DATASUS.",uiOutput("estado_atualizacao"),uiOutput("controle_atualizacao"),uiOutput("estado_agendamento")),
            card("Versão e procedência","Cada extração mantém sua data, seus arquivos e seus identificadores.",uiOutput("proveniencia"),downloadLink("baixar_manifesto","↓ Metadados e fontes",class="botao-link"))),
          card("Como os indicadores são construídos",NULL,
            div(class="grade grade-tres metodo-colunas",
              div(h4("População e notificações"),p("Residentes no Paraná, idade de 15–29 anos, circunstância 10 e agentes tóxicos 01–14 ou 99. Ano de notificação. Não houve deduplicação adicional das notificações."),p(metodo_populacao()),p("O painel segue o método do estudo enviado. A coleta automática atualiza as notificações do SINAN; os denominadores populacionais continuam sendo os do estudo.")),
              div(h4("Bayes, Moran e LISA"),p("Bayes empírico espacial local, implementação GeoDa, média anual de eventos e de população em 2021–2025. Exibição por 100 mil habitantes. Vizinhança Queen de primeira ordem e pesos padronizados por linha."),p("Permutação: 999 simulações, semente 42, pseudo-p folded e p < 0,05. A resposta 1.5 confirmou QUAD_PRM e LISA_P_PRM como referência final do estudo; QUAD_OFIC é histórico. Novas extrações permanecem exploratórias. Associações espaciais não demonstram causalidade.")),
              div(h4("Tempo e reprodutibilidade"),p("Taxas Bayes anuais, Moran global anual, Mann–Kendall e inclinação de Sen em 2014–2025. O painel longo estrutura os dados espaço-temporais; não foi executada a análise Emerging Hot Spot nem gerado um cubo NetCDF."),p("A versão do estudo permanece preservada. Novas versões recalculam resultados exploratórios e registram revisões por ano. A base só é substituída após passar pelas validações.")))),
          card("Revisões em relação ao estudo","Diferença das contagens anuais na última extração automática.",uiOutput("aviso_comparacao"),DT::DTOutput("tabela_revisoes")))
      ),
      tags$footer(class="rodape-principal",span("Intoxicações no Paraná"),span("Pesquisa · exploração de dados agregados")))))
